const cache = {};
function fib(n) {
  if (n < 2) return n;
  if (cache[n] !== undefined) return cache[n];
  cache[n] = fib(n - 1) + fib(n - 2);
  return cache[n];
}
console.log(fib(40));

python.code:
cache = {}

def fib(n):
    if n < 2:
        return n
    if n not in cache:
        cache[n] = fib(n - 1) + fib(n - 2)
    return cache[n]

print(fib(40))
